import{_ as e,C as r,c as t,o as i,j as n,b as l,a0 as s,a,w as o,G as d,a1 as u}from"./chunks/framework.DKRgXLPU.js";const k=JSON.parse('{"title":"Bygg din rutine før inntak","description":"","frontmatter":{},"headers":[],"relativePath":"no/education/mental-strength/pre-shot-routine.md","filePath":"no/education/mental-strength/pre-shot-routine.md"}');const g=e({name:"no/education/mental-strength/pre-shot-routine.md"},[["render",function(e,k,g,h,f,p){const m=r("Mermaid");return i(),t("div",null,[k[1]||(k[1]=n("h1",{id:"bygg-din-rutine-før-inntak",tabindex:"-1"},[a("Bygg din rutine før inntak "),n("a",{class:"header-anchor",href:"#bygg-din-rutine-før-inntak","aria-label":'Permalink to "Bygg din rutine før inntak"'},"​")],-1)),k[2]||(k[2]=n("p",null,"Rutinen din før skuddet er et av de kraftigste verktøyene i ditt mentale spill. Det er en konsekvent sekvens av handlinger som forbereder deg på hvert kast og utløser din beste prestasjonstilstand.",-1)),k[3]||(k[3]=n("div",{class:"tip custom-block"},[n("p",{class:"custom-block-title"},"Den store ideen"),n("p",null,[n("strong",null,"Rutinen din er inngangsporten til sonen."),a(" En konsekvent rutine før treningen signaliserer til hjernen din: «Det er på tide å utføre.» Med repetisjon blir det en automatisk trigger for topp ytelse.")])],-1)),(i(),l(u,null,{default:o(()=>[d(m,{id:"mermaid-11",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BStart%20rutine%5D%20--%3E%20B%5BHjernen%20gjenkjenner%20m%C3%B8nster%5D%0A%20%20%20%20B%20--%3E%20C%5BAutomatisk%20tilstandsskifte%5D%0A%20%20%20%20C%20--%3E%20D%5BUtf%C3%B8relsesmodus%5D%0A%20%20%20%20D%20--%3E%20E%5BTopp%20ytelse%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20C%20fill%3A%23e8f5e9%0A%20%20%20%20style%20D%20fill%3A%23fff4e1%0A%20%20%20%20style%20E%20fill%3A%23fff4e1%0A"})]),fallback:o(()=>[...k[0]||(k[0]=[a(" Loading... ",-1)])]),_:1})),k[4]||(k[4]=s('<h2 id="hvorfor-rutiner-fungerer" tabindex="-1">Hvorfor rutiner fungerer <a class="header-anchor" href="#hvorfor-rutiner-fungerer" aria-label="Permalink to &quot;Hvorfor rutiner fungerer&quot;">​</a></h2><h3 id="konsistens-skaper-tillit" tabindex="-1">Konsistens skaper tillit <a class="header-anchor" href="#konsistens-skaper-tillit" aria-label="Permalink to &quot;Konsistens skaper tillit&quot;">​</a></h3><p>Når du gjør det samme hver gang, fjerner du variabler. Kroppen din vet hva som kommer. Dette skaper en følelse av kontroll og fortrolighet, selv i ukjente situasjoner.</p><h3 id="rutiners-utløsertilstander" tabindex="-1">Rutiners utløsertilstander <a class="header-anchor" href="#rutiners-utløsertilstander" aria-label="Permalink to &quot;Rutiners utløsertilstander&quot;">​</a></h3><p>Med repetisjon blir rutinen din knyttet til prestasjonstilstanden din. Når du starter rutinen, starter det mentale skiftet til utførelsesmodus automatisk.</p><h3 id="rutiner-blokkerer-distraksjoner" tabindex="-1">Rutiner blokkerer distraksjoner <a class="header-anchor" href="#rutiner-blokkerer-distraksjoner" aria-label="Permalink to &quot;Rutiner blokkerer distraksjoner&quot;">​</a></h3><p>En rutine gir tankene dine noe å fokusere på. Det er ikke rom for bekymring for musikken, publikum eller hva som kan skje.</p><h3 id="rutiner-handterer-opphisselse" tabindex="-1">Rutiner håndterer opphisselse <a class="header-anchor" href="#rutiner-handterer-opphisselse" aria-label="Permalink to &quot;Rutiner håndterer opphisselse&quot;">​</a></h3><p>En godt utformet rutine bidrar til å regulere energinivået ditt – den roer deg ned hvis du er for opptatt, og fokuserer deg hvis du er flat.</p><h2 id="elementer-i-en-effektiv-rutine" tabindex="-1">Elementer i en effektiv rutine <a class="header-anchor" href="#elementer-i-en-effektiv-rutine" aria-label="Permalink to &quot;Elementer i en effektiv rutine&quot;">​</a></h2><h3 id="fase-1-vurdering-utenfor-sirkelen" tabindex="-1">Fase 1: Vurdering (utenfor sirkelen) <a class="header-anchor" href="#fase-1-vurdering-utenfor-sirkelen" aria-label="Permalink to &quot;Fase 1: Vurdering (utenfor sirkelen)&quot;">​</a></h3><p>Før du går inn, samle informasjon:</p><ul><li>Les terrenget (bakker, hindringer, underlag)</li><li>Vurder situasjonen (score, kuleposisjoner)</li><li>Velg mål og landingssted</li><li>Bestem deg for kasttype (pek, skyt, lobb, rull)</li></ul><p><strong>Det er her tenkningen skjer.</strong> Ta deg god tid her.</p><h3 id="fase-2-overgang-inntreden-i-sirkelen" tabindex="-1">Fase 2: Overgang (inntreden i sirkelen) <a class="header-anchor" href="#fase-2-overgang-inntreden-i-sirkelen" aria-label="Permalink to &quot;Fase 2: Overgang (inntreden i sirkelen)&quot;">​</a></h3><p>Overgangen fra å tenke til å gjøre:</p><ul><li>Fysisk handling (gå inn i sirkelen på en konsekvent måte)</li><li>Mentalt signal (et ord eller uttrykk som signaliserer &quot;utførelsesmodus&quot;)</li><li>Pust (ett bevisst åndedrag for å sentrere deg)</li></ul><p><strong>Dette er bryteren.</strong> Analysen stopper her.</p><h3 id="fase-3-oppsett-i-sirkelen" tabindex="-1">Fase 3: Oppsett (i sirkelen) <a class="header-anchor" href="#fase-3-oppsett-i-sirkelen" aria-label="Permalink to &quot;Fase 3: Oppsett (i sirkelen)&quot;">​</a></h3><p>Forbered kroppen din:</p><ul><li>Konsekvent holdning (samme hver gang)</li><li>Grepstest (føl på kulen)</li><li>Måljustering</li><li>Fysisk trigger (en liten bevegelse som er din)</li></ul><h3 id="fase-4-visualisering-kortfattet" tabindex="-1">Fase 4: Visualisering (kortfattet) <a class="header-anchor" href="#fase-4-visualisering-kortfattet" aria-label="Permalink to &quot;Fase 4: Visualisering (kortfattet)&quot;">​</a></h3><p>Se kastet før du gjør det:</p><ul><li>Se for deg ballens bane (maks. 2–3 sekunder)</li><li>Føl det vellykkede kastet</li><li>Få visuel kontakt med målet ditt</li></ul><h3 id="fase-5-utførelse" tabindex="-1">Fase 5: Utførelse <a class="header-anchor" href="#fase-5-utførelse" aria-label="Permalink to &quot;Fase 5: Utførelse&quot;">​</a></h3><p>Gjør kastet:</p><ul><li>Eksternt fokus (kun mål)</li><li>Stol på kroppen din</li><li>Slipp uten å nøle</li><li>Følg opp naturlig</li></ul><h2 id="bygge-din-personlige-rutine" tabindex="-1">Bygge din personlige rutine <a class="header-anchor" href="#bygge-din-personlige-rutine" aria-label="Permalink to &quot;Bygge din personlige rutine&quot;">​</a></h2><h3 id="trinn-1-observer-hva-du-allerede-gjør" tabindex="-1">Trinn 1: Observer hva du allerede gjør <a class="header-anchor" href="#trinn-1-observer-hva-du-allerede-gjør" aria-label="Permalink to &quot;Trinn 1: Observer hva du allerede gjør&quot;">​</a></h3><p>Du har sannsynligvis allerede en viss rutine. Merk:</p><ul><li>Hva gjør du før gode kast?</li><li>Hva føles naturlig for deg?</li><li>Hva hjelper deg å fokusere?</li></ul><h3 id="trinn-2-design-rutinen-din" tabindex="-1">Trinn 2: Design rutinen din <a class="header-anchor" href="#trinn-2-design-rutinen-din" aria-label="Permalink to &quot;Trinn 2: Design rutinen din&quot;">​</a></h3><p>Lag en sekvens som inkluderer:</p><ul><li>[ ] Vurderingsfase</li><li>[ ] Klart overgangsøyeblikk</li><li>[ ] Konsekvent fysisk oppsett</li><li>[ ] Kort visualisering</li><li>[ ] Utførelsesutløser</li></ul><h3 id="trinn-3-skriv-det-ned" tabindex="-1">Trinn 3: Skriv det ned <a class="header-anchor" href="#trinn-3-skriv-det-ned" aria-label="Permalink to &quot;Trinn 3: Skriv det ned&quot;">​</a></h3><p>Vær spesifikk. Eksempel:</p><ol><li><strong>Vurder:</strong> Les terrenget, velg landingssted</li><li><strong>Overgang:</strong> Gå inn i sirkelen med venstre fot først, si «tillit»</li><li><strong>Oppsett:</strong> Føtter i skulderbredde, grepssjekk, juster skuldrene</li><li><strong>Visualiser:</strong> Se stien, føl utløsningen</li><li><strong>Utfør:</strong> Blikket festet på målet, kast</li></ol><h3 id="trinn-4-øv-deg-religiøst" tabindex="-1">Trinn 4: Øv deg religiøst <a class="header-anchor" href="#trinn-4-øv-deg-religiøst" aria-label="Permalink to &quot;Trinn 4: Øv deg religiøst&quot;">​</a></h3><p>Bruk rutinen din på HVERT kast på trening:</p><ul><li>Enkle kast</li><li>Vanskelige kast</li><li>Når du er sliten</li><li>Når du er fersk</li></ul><p>Rutinen må bli automatisk.</p><h3 id="trinn-5-avgrens-over-tid" tabindex="-1">Trinn 5: Avgrens over tid <a class="header-anchor" href="#trinn-5-avgrens-over-tid" aria-label="Permalink to &quot;Trinn 5: Avgrens over tid&quot;">​</a></h3><p>Rutinen din vil utvikle seg. Legg merke til hva som fungerer og juster. Men ikke endre den under konkurranser – bare mellom øvelsene.</p><h2 id="rutinemessig-timing" tabindex="-1">Rutinemessig timing <a class="header-anchor" href="#rutinemessig-timing" aria-label="Permalink to &quot;Rutinemessig timing&quot;">​</a></h2><p>Rutinen din bør ta en jevn mengde tid:</p><ul><li>For fort: Du har det forhastet, ikke ordentlig forberedt</li><li>For treg: Du tenker for mye og mister flyten</li><li>Akkurat passe: Nok tid til å forberede seg, ikke så mye at du tenker for mye</li></ul><p><strong>Typisk tidspunkt:</strong></p><ul><li>Vurdering: 5–10 sekunder</li><li>Overgang + Oppsett: 3–5 sekunder</li><li>Visualisering + Utførelse: 3–5 sekunder</li><li><strong>Totalt: 10–20 sekunder</strong></li></ul><h2 id="vanlige-rutinefeil" tabindex="-1">Vanlige rutinefeil <a class="header-anchor" href="#vanlige-rutinefeil" aria-label="Permalink to &quot;Vanlige rutinefeil&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feil</th><th>Problem</th><th>Løsning</th></tr></thead><tbody><tr><td>Hopping i øvelse</td><td>Rutiner er ikke automatiske</td><td>Bruk den hvert eneste kast</td></tr><tr><td>For komplisert</td><td>Vanskelig å huske under press</td><td>Forenkle til det essensielle</td></tr><tr><td>Tenkning under utførelse</td><td>Forstyrrer automatisk ytelse</td><td>Tydelig overgangspunkt</td></tr><tr><td>Inkonsekvent timing</td><td>Skaper usikkerhet</td><td>Øv med jevnt tempo</td></tr><tr><td>Endring midt i konkurransen</td><td>Introduserer tvil</td><td>Hold deg til det du vet</td></tr></tbody></table><h2 id="rutinemessig-feilsøking" tabindex="-1">Rutinemessig feilsøking <a class="header-anchor" href="#rutinemessig-feilsøking" aria-label="Permalink to &quot;Rutinemessig feilsøking&quot;">​</a></h2><p><strong>Hvis du har det travelt:</strong></p><ul><li>Legg til et pust i overgangen</li><li>Senk oppsettbevegelsene dine</li><li>Pause før visualisering</li></ul><p><strong>Hvis du tenker for mye:</strong></p><ul><li>Forkort rutinen</li><li>Bruk en sterkere overgangssignal</li><li>Fokuser mer eksternt</li></ul><p><strong>Hvis du er inkonsekvent:</strong></p><ul><li>Video deg selv for å sjekke</li><li>Øv på rutinen uten å kaste</li><li>Få tilbakemeldinger fra en partner</li></ul><h2 id="eksempelrutiner" tabindex="-1">Eksempelrutiner <a class="header-anchor" href="#eksempelrutiner" aria-label="Permalink to &quot;Eksempelrutiner&quot;">​</a></h2><h3 id="enkel-rutine" tabindex="-1">Enkel rutine <a class="header-anchor" href="#enkel-rutine" aria-label="Permalink to &quot;Enkel rutine&quot;">​</a></h3><ol><li>Velg mål</li><li>Gå inn, pust</li><li>Grip, juster</li><li>Se det, kast det</li></ol><h3 id="detaljert-rutine" tabindex="-1">Detaljert rutine <a class="header-anchor" href="#detaljert-rutine" aria-label="Permalink to &quot;Detaljert rutine&quot;">​</a></h3><ol><li>Les terrenget, velg landingssted</li><li>Gå inn venstre fot først</li><li>Si «glatt» internt</li><li>Ett åndedrag, skuldrene senkes</li><li>Føttene satt, grepssjekk</li><li>Juster skuldrene i forhold til målet</li><li>Se stien (2 sekunder)</li><li>Øynene festes på målet</li><li>Kaste</li></ol><h2 id="viktig-konklusjon" tabindex="-1">Viktig konklusjon <a class="header-anchor" href="#viktig-konklusjon" aria-label="Permalink to &quot;Viktig konklusjon&quot;">​</a></h2><blockquote><p>Rutinen din er ankeret ditt. I kaos er den din konstant.</p></blockquote><p>Bygg det forsiktig. Øv alltid på det. Stol fullt og helt på det.</p>',65))])}]]);export{k as __pageData,g as default};
